import json, hashlib, re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'phaseMicro4-costs-granularity-adaptive-backfill-v1_questions.json'
qs=[]
seq=0
source_id=9500000

def norm(s): return re.sub(r'\s+',' ',str(s).strip()).lower()
def ahash(answer): return hashlib.sha256(norm(answer).encode()).hexdigest()
def shash(obj): return hashlib.sha256(json.dumps(obj,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()

def add(pool,subtopic,objective,skill,q,options,correct,feedback,typ=None,common='misapplies_cost_concept',secondary=None):
    global seq,source_id
    assert pool in ('easy','medium','hard','repair','bridge')
    assert len(options)==4 and len(set(options))==4 and correct in options
    seq+=1; source_id+=1
    rot=(seq-1)%4
    opts=list(options[rot:]+options[:rot])
    role='main' if pool in ('easy','medium','hard') else pool
    diff=pool if role=='main' else 'unknown'
    if typ is None:
        typ={'easy':'concept','medium':'application','hard':'analysis','repair':'repair','bridge':'bridge'}[pool]
    rec={
      'id':f"PMC-COP-{ {'easy':'E','medium':'M','hard':'H','repair':'R','bridge':'BR'}[pool] }-{seq:03d}",
      'q':q,'options':opts,'tag':'costs_of_production','type':typ,'objective':objective,
      'difficulty':pool if role=='main' else pool,'conceptCluster':'micro_costs_of_production',
      'primarySkill':skill,'secondarySkills':[],'repairSkill':skill,'commonError':common,
      'feedback':feedback,'aHash':ahash(correct),'sourceGame':'micro-concept-library',
      'sourceChapter':['costs-of-production'],'sourcePool':pool,'primaryConceptId':'costs-of-production',
      'secondaryConceptIds':secondary or [],'instructionalRole':role,'canonicalDifficulty':diff,
      'originalSourcePool':pool,'originalBossTier':None,'familyConceptId':'costs-of-production',
      'subtopicIds':[subtopic]
    }
    rec['canonicalId']=rec['id']; rec['sourceId']=source_id
    rec['sourceHash']=shash({k:v for k,v in rec.items() if k not in ('sourceHash','sourceOccurrences')})
    rec['sourceOccurrences']=[{'sourceGame':'micro-concept-library','sourceFile':OUT.name,'sourceGlobal':'questions','sourcePool':pool,'routeKey':skill,'sourceRecordOrder':len(qs),'sourceId':source_id,'sourceHash':rec['sourceHash']}]
    qs.append(rec)

